async (page) => {
  const { execSync } = require('child_process');

  try {
    // Make the script executable
    execSync('chmod +x /tmp/mcp-workspace/backup_md.sh');
    console.log('Script made executable');

    // Execute the backup script
    const output = execSync('bash /tmp/mcp-workspace/backup_md.sh', { encoding: 'utf-8' });
    console.log('Script output:\n' + output);

    return 'Backup script executed successfully';
  } catch (error) {
    console.error('Error:', error.message);
    return 'Error: ' + error.message;
  }
}
